502:         const { skill, index } = ranged[Math.floor(Math.random() * ranged.length)];
503:         actor.mana -= skill.cost; actor.skillCooldowns[index] = rand(4, 7);
504:         beginNpcAim(actor, target, skill); continue;
505:       }
506:       if (d <= 1) {
507:         if (actor.attackCd <= 0) beginNpcAim(actor, target);
508:       } else if (actor.aiTimer <= 0) {
509:         let step = nextPathStep(actor, target);
510:         if (step && Math.random() < .16) {
511:           const sideways = [[step[1], -step[0]], [-step[1], step[0]]].sort(() => Math.random() - .5);
512:           const detour = sideways.find(([dx, dy]) => isOpen(actor.x + dx, actor.y + dy) && !occupied(actor.x + dx, actor.y + dy, actor));
513:           if (detour) step = detour;
