543:   function resolveGrh(id, now, animate = true) {
544:     let def = grhs[String(id)];
545:     if (!def) return null;
546:     if (def.frames) {
547:       const index = animate ? Math.floor(now / Math.max(1, def.speed)) % def.frames.length : 0;
548:       def = grhs[String(def.frames[index])];
549:     }
550:     if (!def || !def.image) return null;
551:     return { image: images.get(def.image), def };
552:   }
553:   function screenTile(x, y, cameraX, cameraY) {
