614:   function drawCombatEffects(cameraX, cameraY, now) {
615:     for (const actor of fighters.slice(1)) {
616:       const aim = actor.aim;
617:       if (!aim) continue;
618:       const [sx, sy] = screenTile(aim.x, aim.y, cameraX, cameraY);
619:       const x = sx + tilePx / 2, y = sy + tilePx / 2;
620:       const pulse = .5 + Math.sin(now / 90) * .16;
621:       ctx.save(); ctx.globalAlpha = .72 + pulse * .28;
622:       ctx.strokeStyle = '#ff685b'; ctx.fillStyle = '#ff685b';
