635:       ctx.save(); ctx.fillStyle = placementTile.valid ? 'rgba(144,205,111,.22)' : 'rgba(220,91,76,.22)';
636:       ctx.strokeStyle = placementTile.valid ? '#a9df83' : '#f08070'; ctx.lineWidth = 2;
637:       ctx.fillRect(sx + 2, sy + 2, tilePx - 4, tilePx - 4); ctx.strokeRect(sx + 2, sy + 2, tilePx - 4, tilePx - 4);
638:       ctx.restore();
