643:         ctx.save(); ctx.strokeStyle = selectedSkill === null ? 'rgba(235,211,153,.75)' : 'rgba(255,230,167,.95)';
644:         ctx.lineWidth = Math.max(1.5, tilePx * .055); ctx.setLineDash([tilePx * .12, tilePx * .1]);
645:         ctx.beginPath(); ctx.ellipse(sx + tilePx / 2, sy + tilePx * .88, tilePx * .43, tilePx * .17, 0, 0, Math.PI * 2); ctx.stroke();
