651:       const [x0, y0] = screenTile(effect.x, effect.y, cameraX, cameraY);
652:       const [x1, y1] = screenTile(effect.tx, effect.ty, cameraX, cameraY);
653:       const x = x0 + tilePx / 2 + (x1 - x0) * progress;
654:       const y = y0 + tilePx / 2 + (y1 - y0) * progress;
655:       ctx.save(); ctx.globalAlpha = 1 - progress;
