const fs = require('node:fs');
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  const targets = await (await fetch('http://localhost:9222/json/list')).json();
  const page = targets.find(target => target.type === 'page');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    ws.addEventListener('open', resolve, {once:true});
    ws.addEventListener('error', reject, {once:true});
  });
  let nextId = 0;
  const pending = new Map();
  ws.addEventListener('message', event => {
    const message = JSON.parse(event.data);
    if (!message.id || !pending.has(message.id)) return;
    const {resolve, reject} = pending.get(message.id);
    pending.delete(message.id);
    message.error ? reject(new Error(JSON.stringify(message.error))) : resolve(message.result);
  });
  const call = (method, params={}) => new Promise((resolve, reject) => {
    const id = ++nextId;
    pending.set(id, {resolve, reject});
    ws.send(JSON.stringify({id, method, params}));
  });
  await call('Page.enable');
  await call('Runtime.enable');
  await call('Page.navigate', {url:'http://localhost:3002'});
  await sleep(2500);
  for (const [name, width, height] of [['desktop',1280,900],['mobile',390,844]]) {
    await call('Emulation.setDeviceMetricsOverride', {width,height,deviceScaleFactor:1,mobile:width<600});
    await call('Page.reload', {ignoreCache:true});
    await sleep(2200);
    const image = await call('Page.captureScreenshot', {format:'jpeg',quality:88,fromSurface:true,captureBeyondViewport:false});
    fs.writeFileSync(`/tmp/opencode/${name}-latest.jpg`, Buffer.from(image.data,'base64'));
  }
  ws.close();
})().catch(error => { console.error(error); process.exitCode = 1; });

